--
-- Name: assign_user_to_geographic_channels(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_user_to_geographic_channels() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_channel RECORD;
BEGIN
    -- Only proceed if location fields are set
    IF NEW.geo_state IS NULL AND NEW.geo_district IS NULL AND NEW.geo_municipality IS NULL AND NEW.geo_ward IS NULL THEN
        RETURN NEW;
    END IF;

    -- Find and assign to all matching geographic channels
    FOR v_channel IN 
        SELECT id FROM discussion_channels
        WHERE 
            -- Central committee (all members with any location)
            (location_type = 'central')
            -- State channels
            OR (location_type = 'state' AND NEW.geo_state IS NOT NULL AND location_value = NEW.geo_state)
            -- District channels  
            OR (location_type = 'district' AND NEW.geo_district IS NOT NULL AND location_value = NEW.geo_district)
            -- Municipality channels
            OR (location_type = 'municipality' AND NEW.geo_municipality IS NOT NULL AND location_value = NEW.geo_municipality)
            -- Ward channels (match ward + parent municipality)
            OR (location_type = 'ward' AND NEW.geo_ward IS NOT NULL AND location_value = NEW.geo_ward
                AND parent_channel_id IN (
                    SELECT id FROM discussion_channels 
                    WHERE location_type = 'municipality' AND location_value = NEW.geo_municipality
                ))
    LOOP
        VALUES (v_channel.id, NEW.id, 'member', NOW())
        ON CONFLICT (channel_id, user_id) DO NOTHING;
    END LOOP;

    RETURN NEW;
END;
$$;


--
-- Name: can_access_channel(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_access_channel(p_channel_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_channel RECORD;
    v_user RECORD;
BEGIN
    -- Get channel info
    SELECT access_type, min_role_level, location_scope, visibility 
    INTO v_channel
    FROM discussion_channels 
    WHERE id = p_channel_id;

    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;

    -- Public channels: everyone can access
    IF v_channel.access_type = 'public' OR v_channel.visibility::TEXT = 'public' THEN
        RETURN TRUE;
    END IF;

    -- Check if user is logged in
    IF p_user_id IS NULL THEN
        RETURN FALSE;
    END IF;

    -- Get user info
    SELECT role, state, district, municipality, ward, department 
    INTO v_user
    FROM profiles 
    WHERE id = p_user_id;

    -- Members-only: any logged in user
    IF v_channel.access_type = 'members' THEN
        RETURN TRUE;
    END IF;

    -- Role-based: check role level
    IF v_channel.access_type = 'role_based' THEN
        -- Get user's role level from role_levels table
        DECLARE
            v_user_level INT;
        BEGIN
            SELECT level INTO v_user_level 
            FROM role_levels 
            WHERE key = v_user.role;
            
            RETURN COALESCE(v_user_level, 0) >= COALESCE(v_channel.min_role_level, 0);
        END;
    END IF;

    -- Private: check explicit membership
    IF v_channel.access_type = 'private' THEN
        RETURN EXISTS (
            SELECT 1 FROM channel_members 
            WHERE channel_id = p_channel_id AND user_id = p_user_id
        );
    END IF;

    RETURN FALSE;
END;
$$;


--
-- Name: can_create_subchannel(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_create_subchannel(p_user_id uuid, p_parent_channel_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_parent RECORD;
    v_user RECORD;
BEGIN
    -- Get parent channel info
    SELECT * INTO v_parent FROM discussion_channels WHERE id = p_parent_channel_id;
    IF NOT FOUND THEN RETURN FALSE; END IF;
    
    -- Check if parent allows sub-channel creation
    IF NOT v_parent.can_create_subchannels THEN RETURN FALSE; END IF;
    
    -- Get user's profile
    SELECT * INTO v_user FROM profiles WHERE id = p_user_id;
    IF NOT FOUND THEN RETURN FALSE; END IF;
    
    -- Check user's location matches the channel's location
    CASE v_parent.location_type
        WHEN 'central' THEN
            -- Only admin can create under central
            RETURN v_user.role IN ('admin', 'yantrik');
        WHEN 'state' THEN
            -- State members can create
            RETURN v_user.state = v_parent.location_value;
        WHEN 'district' THEN
            -- District members can create
            RETURN v_user.district = v_parent.location_value;
        WHEN 'municipality' THEN
            -- Municipality members can create
            RETURN v_user.municipality = v_parent.location_value;
        WHEN 'ward' THEN
            -- Ward members can create (if the ward's municipality matches)
            RETURN v_user.ward = v_parent.location_value 
                AND v_user.municipality = (
                    SELECT location_value FROM discussion_channels 
                    WHERE id = v_parent.parent_channel_id
                );
        ELSE
            RETURN FALSE;
    END CASE;
END;
$$;


--
-- Name: cleanup_orphaned_attachments(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_orphaned_attachments() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Delete attachments where post_id is NULL and created > 24 hours ago
    DELETE FROM public.discussion_post_attachments
    WHERE post_id IS NULL
      AND created_at < now() - INTERVAL '24 hours';
      
    -- Note: This does NOT delete the actual file from Storage. 
    -- A separate trigger or edge function would be needed to sync Storage deletions.
    -- For MVP, this clears the DB metadata clutter.
END;
$$;


--
-- Name: find_existing_conversation(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_existing_conversation(user_a uuid, user_b uuid) RETURNS TABLE(conversation_id uuid)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT cp1.conversation_id
    FROM conversation_participants cp1
    INNER JOIN conversation_participants cp2 ON cp1.conversation_id = cp2.conversation_id
    WHERE cp1.user_id = user_a AND cp2.user_id = user_b
    LIMIT 1;
END;
$$;


--
-- Name: get_user_role(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_role(uid uuid) RETURNS public.user_role
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (SELECT role FROM public.user_roles WHERE user_id = uid),
    (SELECT role FROM public.profiles WHERE id = uid),
    'guest'::user_role
  );
$$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  BEGIN
    VALUES (
      NEW.id,
      COALESCE(NEW.raw_user_meta_data->>'full_name',
               NEW.raw_user_meta_data->>'name',
               'Anonymous'),
      COALESCE(NEW.raw_user_meta_data->>'avatar_url',
               NEW.raw_user_meta_data->>'picture'),
      'member'::user_role,
      NOW()
    )
    ON CONFLICT (id) DO UPDATE SET
      full_name   = COALESCE(EXCLUDED.full_name, profiles.full_name),
      avatar_url  = COALESCE(EXCLUDED.avatar_url, profiles.avatar_url),
      updated_at  = NOW();
  EXCEPTION WHEN OTHERS THEN
    -- Don't kill signup. Just log a warning in Postgres logs.
    RAISE WARNING '[handle_new_user] Failed to create profile for user %: %',
                  NEW.id, SQLERRM;
  END;

  RETURN NEW;
END;
$$;


--
-- Name: has_channel_access(public.channel_visibility); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_channel_access(channel_vis public.channel_visibility) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  ur user_role;
BEGIN
  -- 1. Public is always true
  IF channel_vis = 'public' THEN RETURN true; END IF;
  
  -- 2. Non-public requires authentication
  IF auth.role() = 'anon' THEN RETURN false; END IF;
  
  -- 3. Logged-in is true if authenticated
  IF channel_vis = 'logged_in' THEN RETURN true; END IF;
  
  -- 4. Fetch the user's role
  SELECT public.get_user_role(auth.uid()) INTO ur;
  
  -- 5. Party Only visibility
  IF channel_vis = 'party_only' THEN
    RETURN ur IN ('party_member', 'team_member', 'central_committee', 'board', 'admin_party', 'yantrik', 'admin');
  END IF;
  
  -- 6. Leadership/Internal/Central Committee/Board Only visibility
  IF channel_vis IN ('leadership', 'internal', 'central_committee', 'board_only') THEN
    RETURN ur IN ('central_committee', 'board', 'admin_party', 'yantrik', 'admin');
  END IF;

  RETURN false;
END;
$$;


--
-- Name: has_hierarchical_read_access(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_hierarchical_read_access(p_user_id uuid, p_channel_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_channel RECORD;
    v_parent_id UUID;
BEGIN
    -- Check direct membership first
    IF EXISTS (
        SELECT 1 FROM channel_members 
        WHERE channel_id = p_channel_id AND user_id = p_user_id
    ) THEN
        RETURN TRUE;
    END IF;
    
    -- Get channel info
    SELECT * INTO v_channel FROM discussion_channels WHERE id = p_channel_id;
    IF NOT FOUND THEN RETURN FALSE; END IF;
    
    -- Walk up the hierarchy to check parent membership
    v_parent_id := v_channel.parent_channel_id;
    
    WHILE v_parent_id IS NOT NULL LOOP
        -- If user is member of any parent, they have read access
        IF EXISTS (
            SELECT 1 FROM channel_members 
            WHERE channel_id = v_parent_id AND user_id = p_user_id
        ) THEN
            RETURN TRUE;
        END IF;
        
        -- Move to next parent
        SELECT parent_channel_id INTO v_parent_id 
        FROM discussion_channels WHERE id = v_parent_id;
    END LOOP;
    
    RETURN FALSE;
END;
$$;


--
-- Name: FUNCTION has_hierarchical_read_access(p_user_id uuid, p_channel_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.has_hierarchical_read_access(p_user_id uuid, p_channel_id uuid) IS 'Check if user can read a channel through direct membership or parent channel membership (read-down access)';


