    thread_id uuid NOT NULL,
    from_channel_id uuid NOT NULL,
    to_channel_id uuid NOT NULL,
    moved_by uuid NOT NULL,
    move_reason text,
    created_at timestamp with time zone DEFAULT now()
);


--
-- Name: thread_overviews; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.thread_overviews WITH (security_invoker='true') AS
 SELECT t.id,
    t.channel_id,
    t.title,
    t.created_at,
    t.created_by,
    t.is_anonymous,
    t.buried_at,
    t.summary,
    t.meta,
    t.updated_at,
    p.full_name AS author_name,
    p.avatar_url AS author_avatar,
    p.role AS author_role,
    ( SELECT count(*) AS count
           FROM public.discussion_posts p_1
          WHERE (p_1.thread_id = t.id)) AS total_posts,
    ( SELECT p2.id
           FROM public.discussion_posts p2
          WHERE (p2.thread_id = t.id)
          ORDER BY p2.created_at
         LIMIT 1) AS first_post_id,
    ( SELECT p2.content
           FROM public.discussion_posts p2
          WHERE (p2.thread_id = t.id)
          ORDER BY p2.created_at
         LIMIT 1) AS first_post_content,
    ( SELECT count(*) AS count
           FROM public.discussion_votes v
          WHERE ((v.post_id = ( SELECT p2.id
                   FROM public.discussion_posts p2
                  WHERE (p2.thread_id = t.id)
                  ORDER BY p2.created_at
                 LIMIT 1)) AND (v.vote_type = 1))) AS upvotes,
    ( SELECT count(*) AS count
           FROM public.discussion_votes v
          WHERE ((v.post_id = ( SELECT p2.id
                   FROM public.discussion_posts p2
                  WHERE (p2.thread_id = t.id)
                  ORDER BY p2.created_at
                 LIMIT 1)) AND (v.vote_type = '-1'::integer))) AS downvotes
   FROM (public.discussion_threads t
     LEFT JOIN public.profiles p ON ((t.created_by = p.id)))
  WHERE (t.deleted_at IS NULL);


--
-- Name: user_follows; Type: TABLE; Schema: public; Owner: -
